from pathlib import Path

p = Path('gos/standalone.js')
s = p.read_text()

s = s.replace('const VERSION = "0.1.0";', 'const VERSION = "0.1.1";', 1)

marker = 'const BASE_SPACES = ['
idx = s.index(marker)
end = s.index('];', idx) + 2
if 'const MEMORY_TYPES' not in s:
    block = '''\nconst MEMORY_TYPES = Object.freeze({\n  active:["working","episodic","personal","agent","space"],\n  placeholder:["semantic","procedural","global","lineage"]\n});\nconst MEMORY_TYPE_WEIGHT = Object.freeze({working:8,agent:6,personal:5,space:5,episodic:2});\n'''
    s = s[:end] + block + s[end:]

old_retrieval = '''  function relevantMemories(id,pid,sid,query,limit=12){const words=new Set(clean(query,12000).toLowerCase().split(/[^\\p{L}\\p{N}_-]+/u).filter(x=>x.length>=3));return state.memories.filter(m=>m.userId===id&&(!m.personaId||m.personaId===pid)&&(!m.spaceId||m.spaceId===sid)).map(m=>{let score=(m.personaId===pid?8:0)+(m.spaceId===sid?5:0);for(const w of clean(m.text,12000).toLowerCase().split(/[^\\p{L}\\p{N}_-]+/u))if(words.has(w))score+=2;return{m,score};}).sort((a,b)=>b.score-a.score||b.m.createdAt-a.m.createdAt).slice(0,limit).map(x=>x.m);}\n'''
new_retrieval = '''  function tokenizeMemory(v){return [...new Set(clean(v,12000).toLowerCase().split(/[^\\p{L}\\p{N}_-]+/u).filter(x=>x.length>=3))].slice(0,100);}\n  function memoryAlive(m){return !m.expiresAt||Number(m.expiresAt)>now();}\n  function memoryCompatible(m,pid,sid){if(m.personaId&&m.personaId!==pid)return false;if(m.spaceId&&m.spaceId!==sid)return false;if(m.type==="agent"&&!pid)return false;if(m.type==="space"&&!sid)return false;return true;}\n  function rankMemories(id,pid,sid,query,limit=12){\n    const queryWords=new Set(tokenizeMemory(query));\n    return state.memories.filter(m=>m.userId===id&&memoryAlive(m)&&memoryCompatible(m,pid,sid)).map(m=>{\n      let score=Number(MEMORY_TYPE_WEIGHT[m.type]||1),reasons=[`type:${m.type||"unknown"}`];\n      if(m.personaId&&m.personaId===pid){score+=12;reasons.push("persona_scope");}\n      if(m.spaceId&&m.spaceId===sid){score+=8;reasons.push("space_scope");}\n      let overlap=0;for(const w of tokenizeMemory(m.text))if(queryWords.has(w))overlap++;if(overlap){score+=overlap*3;reasons.push(`query_overlap:${overlap}`);}\n      const ageHours=Math.max(0,(now()-Number(m.createdAt||0))/3600000);const recency=Math.max(0,4-ageHours/24);score+=recency;if(recency>0)reasons.push("recent");\n      return{memory:m,score:Number(score.toFixed(3)),reasons};\n    }).sort((a,b)=>b.score-a.score||Number(b.memory.createdAt||0)-Number(a.memory.createdAt||0)).slice(0,Math.max(1,Math.min(50,Number(limit)||12)));\n  }\n  function relevantMemories(id,pid,sid,query,limit=12){return rankMemories(id,pid,sid,query,limit).map(x=>x.memory);}\n'''
if old_retrieval not in s:
    raise SystemExit('old retrieval function not found')
s = s.replace(old_retrieval, new_retrieval, 1)

insert_marker = '  async function runTask'
if 'function createMemory(id,b)' not in s:
    memory_functions = '''  function memorySchema(){return{version:"0.1",active:MEMORY_TYPES.active,placeholder:MEMORY_TYPES.placeholder,workingDefaultTtlMinutes:1440};}\n  function createMemory(id,b){\n    const text=clean(b.text,12000),type=clean(b.type,40).toLowerCase()||"episodic";if(!text)return{ok:false,error:"memory_text_required",status:400};\n    if(!MEMORY_TYPES.active.includes(type))return{ok:false,error:MEMORY_TYPES.placeholder.includes(type)?"memory_type_placeholder":"invalid_memory_type",status:400};\n    let spaceId=clean(b.spaceId,60)||null,personaId=clean(b.personaId,60)||null,taskId=clean(b.taskId,60)||null,scope="user";\n    let space=spaceId?ownedSpace(id,spaceId):null,persona=personaId?ownedPersona(id,personaId):null;\n    if(spaceId&&!space)return{ok:false,error:"space_not_found",status:404};if(personaId&&!persona)return{ok:false,error:"persona_not_found",status:404};\n    if(persona&&spaceId&&persona.spaceId!==spaceId)return{ok:false,error:"persona_space_mismatch",status:400};\n    if(type==="personal"){spaceId=null;personaId=null;scope="personal";}\n    else if(type==="agent"){if(!persona)return{ok:false,error:"persona_required_for_agent_memory",status:400};spaceId=persona.spaceId;scope="agent";}\n    else if(type==="space"){if(!space)return{ok:false,error:"space_required_for_space_memory",status:400};personaId=null;scope="space";}\n    else if(type==="working"){scope=personaId?"agent_working":(spaceId?"space_working":"working");}\n    else if(type==="episodic"){scope=taskId?"task":(personaId?"agent_episode":(spaceId?"space_episode":"episode"));}\n    if(taskId){const task=state.tasks[taskId];if(!task||task.userId!==id)return{ok:false,error:"task_not_found",status:404};}\n    const createdAt=now(),ttlMinutes=type==="working"?Math.max(5,Math.min(10080,Number(b.ttlMinutes)||1440)):null;\n    const item={id:crypto.randomUUID(),userId:id,text,type,scope,spaceId,personaId,taskId,source:clean(b.source,80)||"manual",createdAt,expiresAt:ttlMinutes?createdAt+ttlMinutes*60000:null};\n    state.memories.push(item);state.experienceEvents.push({id:crypto.randomUUID(),userId:id,spaceId,personaId,taskId,type:"memory_created",data:{memoryId:item.id,memoryType:type,scope},createdAt});persist();return{ok:true,item};\n  }\n  function listMemories(id,url){\n    const type=clean(url.searchParams.get("type"),40).toLowerCase(),spaceId=clean(url.searchParams.get("spaceId"),60),personaId=clean(url.searchParams.get("personaId"),60),q=clean(url.searchParams.get("q"),500),limit=Math.max(1,Math.min(200,Number(url.searchParams.get("limit"))||100));\n    let items=state.memories.filter(m=>m.userId===id&&memoryAlive(m));if(type)items=items.filter(m=>m.type===type);if(spaceId)items=items.filter(m=>m.spaceId===spaceId);if(personaId)items=items.filter(m=>m.personaId===personaId);if(q){const words=tokenizeMemory(q);items=items.filter(m=>words.some(w=>clean(m.text,12000).toLowerCase().includes(w)));}\n    return items.sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0)).slice(0,limit);\n  }\n  function retrieveMemories(id,url){\n    const q=clean(url.searchParams.get("q"),12000),spaceId=clean(url.searchParams.get("spaceId"),60)||null,personaId=clean(url.searchParams.get("personaId"),60)||null,limit=Math.max(1,Math.min(50,Number(url.searchParams.get("limit"))||12));\n    if(spaceId&&!ownedSpace(id,spaceId))return{ok:false,error:"space_not_found",status:404};if(personaId&&!ownedPersona(id,personaId))return{ok:false,error:"persona_not_found",status:404};\n    const persona=personaId?ownedPersona(id,personaId):null;if(persona&&spaceId&&persona.spaceId!==spaceId)return{ok:false,error:"persona_space_mismatch",status:400};\n    return{ok:true,query:q,spaceId,personaId,items:rankMemories(id,personaId,spaceId,q,limit)};\n  }\n'''
    s = s.replace(insert_marker, memory_functions + insert_marker, 1)

old_route = '''if(req.method==="GET"&&url.pathname==="/api/gos/memory")return json(res,200,{ok:true,items:state.memories.filter(x=>x.userId===id).slice().sort((a,b)=>b.createdAt-a.createdAt)});'''
new_route = '''if(req.method==="GET"&&url.pathname==="/api/gos/memory/schema")return json(res,200,{ok:true,schema:memorySchema()});if(req.method==="POST"&&url.pathname==="/api/gos/memory"){const out=createMemory(id,b);return json(res,out.ok?201:(out.status||400),out);}if(req.method==="GET"&&url.pathname==="/api/gos/memory/retrieve"){const out=retrieveMemories(id,url);return json(res,out.ok?200:(out.status||400),out);}if(req.method==="GET"&&url.pathname==="/api/gos/memory")return json(res,200,{ok:true,items:listMemories(id,url)});'''
if old_route not in s:
    raise SystemExit('memory route marker not found')
s = s.replace(old_route, new_route, 1)
p.write_text(s)

# Extend the integration test with taxonomy, create/filter/retrieval checks.
p = Path('tests/gos-core-smoke.js')
s = p.read_text()
marker = '''    const cycle = await request("/api/gos/tasks/run", {\n      method:"POST",\n      body:{conversationId,installSecret,spaceId:home.id,personaId:cloned.body.persona.id,input:"Return the first working G-OS result."}\n    });'''
if marker not in s:
    raise SystemExit('task marker not found in smoke test')
if 'Memory Core v0.1 retrieval failed' not in s:
    block = '''    const memorySchema = await request(`/api/gos/memory/schema?conversationId=${conversationId}&installSecret=${installSecret}`);\n    assert(memorySchema.status === 200 && memorySchema.body.schema?.active?.includes("agent"), "memory schema missing active types");\n    assert(memorySchema.body.schema?.placeholder?.includes("lineage"), "memory schema placeholders missing");\n\n    const personalMemory = await request("/api/gos/memory", {method:"POST",body:{conversationId,installSecret,type:"personal",text:"The user prefers concise cold purple interfaces."}});\n    assert(personalMemory.status === 201 && personalMemory.body.item?.type === "personal", "personal memory create failed");\n    const spaceMemory = await request("/api/gos/memory", {method:"POST",body:{conversationId,installSecret,type:"space",spaceId:home.id,text:"HOME is the base control center for core operations."}});\n    assert(spaceMemory.status === 201 && spaceMemory.body.item?.scope === "space", "space memory create failed");\n    const agentMemory = await request("/api/gos/memory", {method:"POST",body:{conversationId,installSecret,type:"agent",personaId:cloned.body.persona.id,text:"Core Tester Clone specializes in evidence-first analysis."}});\n    assert(agentMemory.status === 201 && agentMemory.body.item?.personaId === cloned.body.persona.id, "agent memory create failed");\n    const workingMemory = await request("/api/gos/memory", {method:"POST",body:{conversationId,installSecret,type:"working",spaceId:home.id,personaId:cloned.body.persona.id,ttlMinutes:30,text:"Current benchmark focus is evidence analysis."}});\n    assert(workingMemory.status === 201 && workingMemory.body.item?.expiresAt > workingMemory.body.item?.createdAt, "working memory TTL missing");\n\n    const retrieval = await request(`/api/gos/memory/retrieve?conversationId=${conversationId}&installSecret=${installSecret}&spaceId=${home.id}&personaId=${cloned.body.persona.id}&q=evidence%20analysis&limit=10`);\n    assert(retrieval.status === 200 && retrieval.body.items?.length >= 2, "Memory Core v0.1 retrieval failed");\n    assert(retrieval.body.items.some(x => x.memory?.id === agentMemory.body.item.id), "agent memory not retrieved for its Persona");\n    assert(retrieval.body.items[0]?.score >= retrieval.body.items[retrieval.body.items.length-1]?.score, "retrieval scores not sorted");\n    assert(Array.isArray(retrieval.body.items[0]?.reasons), "retrieval reasons missing");\n\n    const globalRetrieval = await request(`/api/gos/memory/retrieve?conversationId=${conversationId}&installSecret=${installSecret}&q=evidence%20analysis`);\n    assert(!globalRetrieval.body.items.some(x => x.memory?.id === agentMemory.body.item.id), "agent memory leaked outside Persona scope");\n\n'''
    s = s.replace(marker, block + marker, 1)
p.write_text(s)
